function goalChips(l){const g=LESSON_GOALS[curriculum.id],ids=g?.lessons[l.id]||[];return ids.length?`<p class="goal-chips">${ids.map(id=>`<a class="goal-chip" href="#/guide/goal/${encodeURIComponent(id)}">🎯 ${t('लक्ष्य','Goal')}: ${e(g.titles[id][prefs.lang]||g.titles[id].hi)}</a>`).join('')}</p>`:'';}
function guideLink(l){const label=dayLabel(DAY_TYPES[curriculum.id],l,prefs.lang);return `<p class="guide-link"><a href="#/guide/week">📘 ${label?`${t('दिन','Day')} ${l.day} · ${e(label)} — `:''}${t('सप्ताह कैसे चलता है','How the week runs')} →</a></p>`;}
function helpScreen(){return `<div class="help-copy"><a class="button" href="${e(helpReturn)}">← ${t('वापस जाएँ','Go back')}</a><h1>${t('ऐप कैसे इस्तेमाल करें','How to use this app')}</h1><p class="guide-link"><a href="#/guide">📘 ${t('संदर्शिका को समझें: साल के लक्ष्य, सप्ताह और कालांश','Understand the guide: goals, the week and the periods')} →</a></p><section class="panel"><h2>1. ${t('पाठ चुनें और पढ़ाएँ','Choose a lesson and teach')}</h2><p>${t('कक्षा चुनें। विषय या सप्ताह से पाठ खोलें। पूरा पाठ नीचे पढ़ें या ऊपर किसी भाग पर दबाएँ। चित्र बड़ा करने के लिए चित्र पर दबाएँ। पुस्तक से लौटने के लिए “पाठ पर लौटें” या Back दबाएँ।','Choose a grade, then browse by topic or week. Read the whole lesson by scrolling, or use the section chips. Tap an image to enlarge it. Use “Back to lesson” or Back to close a book.')}</p></section><section class="panel"><h2>2. ${t('सूची, ऑफलाइन प्रति और फ़ाइल','Your list, offline copies and files')}</h2><p>${t('“मेरी सूची में जोड़ें” से पाठ फिर खोजना आसान होता है। इंटरनेट बंद करने से पहले “बिना इंटरनेट के लिए रखें” दबाएँ और “पृष्ठ जाँचे गए” आने दें। ये पाठ मेरी सूची पृष्ठ के ऑफलाइन भाग में मिलेंगे। पूरी पुस्तक के सभी पृष्ठ अपने-आप नहीं रखे जाते।','“Add to my list” bookmarks a lesson. Before losing internet access, tap “Keep for offline use” and wait for “Pages checked”. Find these lessons in the offline section of My list. Other pages of the complete book are not automatically stored.')}</p><p>${t('पुस्तक या कार्यपत्रक खोलकर उसी पृष्ठ की फ़ाइल डाउनलोड या प्रिंट का पूर्वावलोकन कर सकते हैं। फ़ाइल ब्राउज़र के Downloads में मिलेगी।','Open a book or worksheet to download that page as a file or preview it for printing. Files go to your browser’s Downloads.')}</p></section><section class="panel"><h2>3. ${t('मेरे नोट कहाँ रहते हैं?','Where are my notes?')}</h2><p>${t('नोट, पढ़ाए गए चिह्न और सूची केवल इस उपकरण के इसी ब्राउज़र में रहते हैं। दूसरे फ़ोन या ब्राउज़र में अपने-आप नहीं आते। ब्राउज़र का डेटा मिटाने या निजी विंडो बंद करने पर खो सकते हैं। नोट की प्रति समय-समय पर फ़ाइल में लें।','Notes, taught marks and your list stay in this browser on this device. They do not sync to another phone or browser. Clearing browser data or closing a private window can lose them. Download a copy of your notes periodically.')}</p><button class="button" data-export-notes>${t('मेरे नोट की फ़ाइल लें','Download my notes')}</button><p class="small">${t('यह पढ़ने योग्य टेक्स्ट फ़ाइल है। ऐप में अपने-आप वापस नहीं आएगी; ज़रूरत पर नोट कॉपी कर सकते हैं।','This is a readable text file. It does not restore notes automatically; you can copy notes back when needed.')}</p></section><section class="panel"><h2>${t('पृष्ठ न खुले या पाठ में गलती हो','If a page fails or content looks wrong')}</h2><p>${t('इंटरनेट जाँचकर “फिर प्रयास करें” दबाएँ। मूल पृष्ठ से पाठ मिलाएँ। पाठ के “मूल पृष्ठ” भाग में “गलती बताएँ” से विवरण फ़ाइल लें, समस्या लिखें और अपने सहायता देने वाले व्यक्ति को साझा करें। ऐप खुद कोई संदेश नहीं भेजता।','Check your connection and retry. Compare the original page. In a lesson’s Sources section, use “Report a lesson issue” to download its details, add a description and share with your support contact. The app does not send messages.')}</p><p>${t('साप्ताहिक रूपरेखा में अपनी गतिविधि, सामग्री और समय की तैयारी नोट में लिखें। English चुनने से केवल मेनू और बटन बदलते हैं; मूल पाठ अपनी भाषा में रहता है।','Weekly outlines require your own activity, material and timing preparation in the notes. English changes menus and buttons; original lesson text keeps its source language.')}</p></section></div>`;}
function notesHTML(l){if(!dirty.has(l.id))notes[l.id]=readObj('-notes')[l.id]||'';return `<section class="panel notes lesson-section" id="lesson-notes" aria-labelledby="notes-title"><h2 id="notes-title" tabindex="-1">${l.structure==='weekly-template'?t('मेरी तैयारी','My preparation'):t('मेरा नोट','My teaching note')}</h2><label for="lesson-note">${t('इस पाठ के लिए क्या याद रखना है? जैसे: कल तीलियाँ लानी हैं।','What should I remember? For example: bring counting sticks tomorrow.')}</label><textarea id="lesson-note" data-note="${e(l.id)}" maxlength="10000">${e(notes[l.id]||'')}</textarea><div class="notes-footer"><span id="note-status">${t('केवल इसी उपकरण पर सहेजा जाता है।','Saved on this device only.')}</span><button class="button" data-save-note>${t('नोट सहेजें','Save note')}</button></div></section>`;}
function preparation(l){const blocks=[
 [t('सामग्री','Materials'),l.materials],
 [t('पहले से क्या आना चाहिए','Prior learning'),l.priorKnowledge?[l.priorKnowledge]:[]],
 [t('नए शब्द','Key words'),l.vocabulary||[]],
 [t('ध्यान दें','Watch for'),l.commonMistake?[l.commonMistake]:[]]
];return `<section class="panel preparation lesson-section" id="lesson-preparation" aria-labelledby="preparation-title"><div class="preparation-heading"><h2 id="preparation-title" tabindex="-1">${t('पढ़ाने से पहले','Before teaching')}</h2><span class="small">${e(curriculum.subjectLabel[prefs.lang])} · ${duration(l)}</span></div>${displayText(l.outcome)!==displayText(l.title)?`<p class="preparation-goal"><strong>${t('सीखने का उद्देश्य','Learning goal')}</strong> ${e(l.outcome)}</p>`:''}<div class="preparation-grid">${blocks.filter(([,items])=>items.length).map(([label,items])=>`<div><h3>${label}</h3><p>${items.map(e).join(' · ')}</p></div>`).join('')}</div>${l.relatedObjectives?.length?`<div class="preparation-assessment"><h3>${t('इस सप्ताह के उद्देश्य','This week’s goals')}</h3>${list(l.relatedObjectives)}</div>`:''}<div class="preparation-assessment"><h3>${t('समझ की जाँच','Check understanding')}</h3>${list(l.assessment)}</div>${l.loCode?`<p class="learning-code">${e(curriculum.outcomeLabel?.[prefs.lang]||t('सीखने का कोड','Learning code'))} <strong>${e(l.loCode)}</strong> · ${e(l.loStatement||'')}</p>`:''}</section>`;}
const {cropMarkup,visualCaption,visualAlt,phaseArtwork,worksheetView}=createLessonMedia({curriculum,prefs,t,e,stage,list});

function phaseView(l,n){const p=l.phases[n],isTemplate=l.structure==='weekly-template',visual=phaseVisual(l,p,curriculum.visualStyle),instructions=teachingInstructions(l,p);
 return `<section id="lesson-phase-${n}" data-phase="${n}" class="lesson-section phase-card ${(p.role||p.id)==='practice'?'practice':(p.role||p.id)==='support'?'support':'teaching'} ${visual?'has-artwork':''} ${isTemplate?'weekly-plan':''}" aria-labelledby="phase-title-${n}"><header class="phase-heading"><div class="phase-heading-title"><span class="phase-number" aria-hidden="true">${t('चरण','Step')} ${n+1}</span><div><span class="eyebrow">${isTemplate?t('साप्ताहिक योजना','Weekly plan'):(curriculum.useUPStageLabels?t('कालांश','Period')+' '+(p.id==='practice'?2:p.id==='support'?3:1):p.period?t('कालांश','Period')+' '+e(p.period):t('चरण','Section'))}</span><h2 id="phase-title-${n}" tabindex="-1">${e(p.id==='practice'?(l.worksheets?.length?t('कार्यपत्रक से अभ्यास','Worksheet practice'):t('कॉपी में अभ्यास','Notebook practice')):stage(p))}</h2></div></div>${p.minutes?`<span class="time"><span aria-hidden="true">◷</span> ${curriculum.phaseTimingNotes?.[l.id]?.[p.id]?.[prefs.lang]||p.minutes+' '+t('मिनट','min')}</span>`:''}</header><div class="phase-body">${p.id==='practice'&&!l.worksheets?.length?`<p class="callout">${t('इस पाठ का अलग कार्यपत्रक उपलब्ध नहीं है। कॉपी में नीचे दिया अभ्यास कराएँ।','No separate worksheet was supplied for this lesson. Use the notebook practice below.')}</p>`:''}${p.adapted?`<p class="adaptation-note">${t('संदर्शिका और कार्यपुस्तिका पर आधारित शिक्षण सहायता','Teaching support adapted from guide and workbook')}</p>`:''}<div class="phase-layout">${phaseArtwork(l,p,n)}<div class="phase-directions">${instructions.length?`<h3 class="content-label">${t('क्या करें','What to do')}</h3><ol class="actions">${instructions.map(x=>`<li>${e(x)}</li>`).join('')}</ol>`:''}${p.id==='practice'&&!l.worksheets?.length?`<button class="text-button" data-section="lesson-phase-${l.phases.findIndex(p=>p.id==='you-do')}">${t('बच्चों का स्वयं अभ्यास वाला भाग खोलें','Go to independent practice')}</button>`:''}</div>${p.questions?.length?`<div class="question-box"><h3><span class="question-mark" aria-hidden="true">?</span> ${t('बच्चों से पूछें','Ask children')}</h3>${list(p.questions)}</div>`:''}</div>${p.id==='practice'||p.worksheetPreview||isTemplate?worksheetView(l):''}${p.id==='support'&&l.phases.some(item=>item.id==='we-do')?`<button class="text-button" data-section="lesson-phase-${l.phases.findIndex(item=>item.id==='we-do')}">${t('साथ में अभ्यास वाला भाग फिर देखें','Revisit guided practice')}</button>`:''}</div></section>`;}

function lessonScreen(){const l=getLesson(LESSONS,route.id);if(!l)return `<section class="panel"><h1>${t('पाठ नहीं मिला','Lesson not found')}</h1><p>${t('यह लिंक उपलब्ध पाठ से नहीं जुड़ा है। सूची से पाठ चुनें।','This link does not match an available lesson. Choose one from the list.')}</p><a class="button primary" href="#/find">${t('पाठ चुनें','Choose a lesson')}</a></section>`;
 const n=Math.min(route.view==='prepare'?Number(phases[l.id])||0:route.step,l.phases.length-1);phases=readObj('-phases');prefs.grade=l.grade;prefs.week=l.week;prefs.openTopic=l.topic;prefs.locations[l.grade]={week:l.week};persist();const selectedURL=new URL(location.href);if(selectedURL.searchParams.has('grade')&&Number(selectedURL.searchParams.get('grade'))!==l.grade){selectedURL.searchParams.set('grade',String(l.grade));history.replaceState(history.state,'',selectedURL);}const seq=neighbours(LESSONS,l.id),isSaved=saved.includes(l.id),isDone=!!completed[l.id];{const opened=readObj('-opened-by-grade');if(opened[l.grade]!==l.id){opened[l.grade]=l.id;store.set(KEY+'-opened-by-grade',opened);}}
 $('#print-root').innerHTML=`<h1>${e(l.title)}</h1><p>${e(gradeLabel(curriculum,l.grade,prefs.lang))} · ${t('सप्ताह','Week')} ${l.week} · ${t('दिन','Day')} ${l.day}</p><img src="${e(l.source.image)}" alt="${t('मूल संदर्शिका पृष्ठ','Original guide page')}">`;
 return `<div class="lesson-context"><a href="#/${prefs.returnTo}">← ${returnLabel(prefs.returnTo)}</a><span>${e(gradeLabel(curriculum,l.grade,prefs.lang))} · ${t('सप्ताह','Week')} ${l.week} · ${t('दिन','Day')} ${l.day}</span></div>${smartCard(l)||`<div class="guide-banner"><div class="guide-calendar"><span>${t('सप्ताह','Week')} ${l.week}</span><strong>${t('दिन','Day')} ${l.day}</strong></div><div><p class="lesson-hierarchy">${e(gradeLabel(curriculum,l.grade,prefs.lang))} · ${e(curriculum.subjectLabel[prefs.lang])} · ${e(l.topic)}</p><h1 class="lesson-title">${e(lessonTitle(l))}</h1>${bannerGoals(l)}</div></div>${chainLine(l)}`}${sectionChips(l,n)}<details class="lesson-options"><summary>⚙ ${t('पाठ के विकल्प','Lesson options')}<span>${t('मेरी सूची · बिना इंटरनेट · अक्षर का आकार','My list · offline · text size')}</span></summary>${lessonTools(l)}${guideLink(l)}</details>${preparation(l)}${l.structure==='weekly-template'?`<p class="callout">${t('यह साप्ताहिक रूपरेखा है। गतिविधि, सामग्री और समय की अपनी तैयारी लिखें।','This is a weekly outline. Prepare your activities, materials and timing.')} <button class="text-button" data-section="lesson-notes">${t('अपनी तैयारी लिखें','Write my preparation')} →</button></p>`:''}<div class="lesson-phases">${l.phases.map((p,i)=>(curriculum.useUPStageLabels&&l.structure!=='weekly-template'&&(i===0||p.id==='practice'||p.id==='support')?`<h2 class="period-heading">${t('कालांश','Period')} ${p.id==='practice'?2:p.id==='support'?3:1}</h2>`:'')+phaseView(l,i)).join('')}</div><div class="lesson-complete" id="lesson-completion" role="status">${isDone?`<p>✓ ${t('यह पाठ पढ़ाया गया चिह्नित है।','This lesson is marked taught.')}</p>${doneNext(l)}<button class="button" data-complete="${l.id}" data-undo>${t('पढ़ाया गया चिह्न हटाएँ','Undo taught mark')}</button>`:`<button class="button primary" data-complete="${l.id}">✓ ${t('पढ़ा दिया है · चिह्न लगाएँ','I have taught this · mark taught')}</button>`}</div>${notesHTML(l)}<section class="panel references lesson-section" id="lesson-references" aria-labelledby="references-title"><h2 id="references-title" tabindex="-1">${t('मूल पुस्तकें और पृष्ठ','Original books and pages')}</h2><p>${e(l.textbookReference||'')}</p><button class="text-button" data-content-report="${l.id}">${t('पाठ में गलती बताएँ · विवरण फ़ाइल लें','Report a lesson issue · get details file')}</button><div class="resource-buttons" id="lesson-book-buttons">${bookButtons(l)}</div><p class="small">${e(l.source.notice)}</p><p class="small">${t('संदर्शिका का विषय','Guide topic')}: ${e(l.topic)} · ${t('उपविषय','Sub-topic')}: ${e(l.subtopic)}${l.loCode?' · '+e(l.loCode):''}</p></section><section class="sequence-menu"><h2>${t('दूसरा दिन चुनें','Choose another day')}</h2>${seq.previous?`<a href="${path(seq.previous)}">← ${t('सप्ताह','Week')} ${seq.previous.week} · ${t('दिन','Day')} ${seq.previous.day}: ${e(lessonTitle(seq.previous))}</a>`:`<p>${t('यह पहला उपलब्ध पाठ है।','This is the first available lesson.')}</p>`}${seq.next?`<a href="${path(seq.next)}">${t('सप्ताह','Week')} ${seq.next.week} · ${t('दिन','Day')} ${seq.next.day}: ${e(lessonTitle(seq.next))} →</a>`:`<p>${t('यह अंतिम उपलब्ध पाठ है।','This is the last available lesson.')}</p>`}</section>`;}
function sectionLabel(section){
 if(section.kind==='preparation')return t('तैयारी','Prepare');
 if(section.kind==='notes')return t('मेरा नोट','Notes');
 if(section.kind==='references')return t('मूल पृष्ठ','Sources');
 const short={conversation:t('बातचीत','Talk'),'i-do':t('मैं करूँ','I do'),'we-do':t('हम करें','We do'),'you-do':t('बच्चे करें','You do'),practice:t('अभ्यास','Practice'),support:t('सहायता','Support')};
 return curriculum.useUPStageLabels?short[section.phase.id]||stage(section.phase):stage(section.phase);
}
function sectionChips(l,n){return `<nav class="lesson-section-nav" aria-label="${t('पूरे पाठ का क्रम','Full lesson sequence')}"><div class="section-chips">${lessonSections(l).map(section=>`<a class="section-chip ${section.kind==='phase'?(section.phase.role||section.phase.id)==='practice'?'chip-practice':(section.phase.role||section.phase.id)==='support'?'chip-support':'chip-teaching':''}" data-section="${section.id}" href="${section.kind==='preparation'?'#/lesson/'+encodeURIComponent(l.id)+'/prepare':path(l,section.index??n)}" aria-controls="${section.id}" aria-label="${e(section.kind==='phase'?stage(section.phase):sectionLabel(section))}${section.phase?.minutes?' · '+section.phase.minutes+' '+t('मिनट','min'):''}" ${(n===0?section.kind==='preparation':section.index===n)?'aria-current="location"':''}>${section.kind==='phase'?`<span class="chip-number">${section.index+1}</span>`:''}<span>${e(sectionLabel(section))}</span>${section.phase?.minutes?`<span class="chip-time">${section.phase.minutes} ${t('मि.','min')}</span>`:''}</a>`).join('')}</div></nav>`;}
let sectionResizeObserver,scrollFrame,activeSection;
function setupLessonNavigation(){
 sectionResizeObserver?.disconnect();activeSection=null;updateCurrentContext();
 const nav=main.querySelector('.lesson-section-nav');if(!nav)return;
 const measure=()=>main.style.setProperty('--section-nav-height',`${nav.offsetHeight+$('#current-context').offsetHeight+16}px`);
 measure();requestAnimationFrame(()=>{if(route.screen!=='lesson'||!nav.isConnected)return;const positions=lessonSections(getLesson(LESSONS,route.id)).map(section=>({id:section.id,top:document.getElementById(section.id)?.getBoundingClientRect().top??Infinity}));const id=sectionAtOffset(positions,nav.getBoundingClientRect().bottom+24);if(id)activateSection(id,{remember:false});});if('ResizeObserver'in window){sectionResizeObserver=new ResizeObserver(measure);sectionResizeObserver.observe(nav);}
}
function activateSection(id,{remember=true}={}){
 const l=route.screen==='lesson'&&getLesson(LESSONS,route.id);if(!l||activeSection===id||remember&&!canTrackLesson(route,parseRoute(location.hash)))return;
 activeSection=id;updateCurrentContext();
 main.querySelectorAll('[data-section]').forEach(chip=>{if(chip.dataset.section===id)chip.setAttribute('aria-current','location');else chip.removeAttribute('aria-current');});
 const section=lessonSections(l).find(s=>s.id===id);
 if(remember&&section?.kind==='phase'){
  phases=readObj('-phases');phases[l.id]=section.index;store.set(KEY+'-phases',phases);
  last={id:l.id,view:'teach',step:section.index};store.set(KEY+'-last',last);const byGrade=readObj('-last-by-grade');byGrade[l.grade]=last;store.set(KEY+'-last-by-grade',byGrade);
  history.replaceState(null,'',path(l,section.index));route=parseRoute(location.hash);
 }
}
function jumpToSection(id,{remember=true,focus=true}={}){
 const section=document.getElementById(id);if(!section)return;
 clearTimeout(noteTimer);flushNotes();activateSection(id,{remember});
 section.scrollIntoView({block:'start',behavior:'instant'});
 if(focus)section.querySelector('h2')?.focus({preventScroll:true});
}
function alignLessonRoute(){
 if(route.screen!=='lesson')return;
 const l=getLesson(LESSONS,route.id);if(!l)return;
 const n=Math.min(route.step,l.phases.length-1);
 if(route.view==='teach'&&n>0)jumpToSection(`lesson-phase-${n}`,{focus:false});
}
window.addEventListener('scroll',()=>{
 if(scrollFrame)return;
 scrollFrame=requestAnimationFrame(()=>{
  scrollFrame=null;if(!canTrackLesson(route,parseRoute(location.hash)))return;const nav=main.querySelector('.lesson-section-nav');if(!nav||$('#reader').open)return;
  const l=getLesson(LESSONS,route.id);if(!l)return;
  const positions=lessonSections(l).map(s=>({id:s.id,top:document.getElementById(s.id).getBoundingClientRect().top}));
  const id=sectionAtOffset(positions,Math.max(nav.getBoundingClientRect().bottom,0)+24);
  if(id)activateSection(id);
 });
},{passive:true});
function render({focus=false,restore}={}){route=parseRoute(location.hash);if(route.screen==='lesson'&&!getLesson(LESSONS,route.id)){const target=packForLessonId(CURRICULA,route.id,groupKey(curriculum));if(target&&target.pack.id!==curriculum.id){clearTimeout(noteTimer);flushNotes();location.replace(lessonURL(location.href,target.pack,target.grade,prefs.lang));return;}}document.documentElement.lang=prefs.lang;$('#ui-language').value=prefs.lang;$('.brand').setAttribute('aria-label',t('संदर्शिका का मुख्य पृष्ठ','Guidebook home'));$('.brand-name').textContent=t('संदर्शिका','Guidebook');$('#today-link').textContent=t('आज','Today');$('#year-link').textContent=t('पूरा साल','Whole year');$('#find-link').textContent=t('सभी पाठ','All lessons');$('.skip-link').textContent=t('पाठ की सामग्री पर जाएँ','Skip to lesson content');$('#ui-language').setAttribute('aria-label',t('भाषा चुनें','Choose language'));$('.header-inner nav').setAttribute('aria-label',t('मुख्य नेविगेशन','Main navigation'));$('#today-link').setAttribute('aria-current',route.screen==='today'?'page':'false');$('#year-link').setAttribute('aria-current',route.screen==='guide'?'page':'false');$('#find-link').setAttribute('aria-current',route.screen==='find'||route.screen==='saved'?'page':'false');main.style.setProperty('--reading-scale',prefs.readingScale);main.dataset.largeText=prefs.readingScale>1.25?'true':'false';main.dataset.view=route.screen;const shownLesson=route.screen==='lesson'&&getLesson(LESSONS,route.id);main.dataset.guideGrade=shownLesson?.grade??prefs.grade;main.dataset.guideWeeklyDay=shownLesson?.structure==='weekly-template'?shownLesson.day:'';main.dataset.guideProfile=curriculum.visualStyle?.layouts?.[shownLesson?.grade??prefs.grade]||'';for(const [role,color] of Object.entries(lessonPalette(shownLesson||{grade:prefs.grade},curriculum.visualStyle)))main.style.setProperty('--guide-'+role,color);$('#print-root').innerHTML='';try{main.innerHTML=(!store.available?`<p class="callout">${t('इस उपकरण पर सहेजना उपलब्ध नहीं है। नोट केवल पृष्ठ खुला रहने तक रहेंगे।','Device saving is unavailable. Notes last only while this page stays open.')}</p>`:'')+(route.screen==='lesson'?lessonScreen():route.screen==='saved'?savedScreen():route.screen==='help'?helpScreen():route.screen==='guide'?guideScreen():route.screen==='today'?todayScreen():findScreen());$('#curriculum-navigation').innerHTML=renderCurriculumSwitcher({packs:CURRICULA,pack:curriculum,grade:prefs.grade,lang:prefs.lang,e,options});$('#curriculum-navigation').setAttribute('aria-label',t('कक्षा और विषय','Grade and subject'));document.title=(route.screen==='lesson'?(getLesson(LESSONS,route.id)?lessonTitle(getLesson(LESSONS,route.id)):t('पाठ नहीं मिला','Lesson not found')):route.screen==='saved'?t('मेरी सूची','My list'):route.screen==='help'?t('मदद','Help'):route.screen==='guide'?(programGuide()?.title(route.section)||t('संदर्शिका को समझें','Understand the guide')):t('पाठ चुनें','Choose a lesson'))+' · '+t('संदर्शिका','Guidebook');if(focus){main.focus({preventScroll:true});window.scrollTo(0,0);}if(restore)document.getElementById(restore)?.focus({preventScroll:true});setupLessonNavigation();for(const el of main.querySelectorAll('[data-offline-controls]'))if(offline[el.dataset.offlineControls])checkOffline(el.dataset.offlineControls);}catch(err){console.error(err);main.innerHTML=`<section class="panel"><h1>${t('पाठ नहीं खुल पाया','Lesson could not load')}</h1><a class="button" href="#/find">${t('पाठ सूची पर लौटें','Return to lessons')}</a></section>`;}}
const {bookButtons,openReader,openVisual,previewPrint}=createReader({$,t,e,options,curriculum,repository:resourceRepository,getCurrentLesson:()=>getLesson(LESSONS,route.id),notify,stage,cropMarkup,visualAlt,visualCaption});
const offlineController=createOfflineController({LESSONS,curriculum,CURRICULA,store,readObj,t,main,notify,render,version:VERSION,getOffline:()=>offline,setOffline:value=>{offline=value;}});
const {offlineControls,checkOffline,keepOffline,removeOffline}=offlineController;
function lessonTools(l){return `<label class="reading-control" for="reading-size">${t('पाठ के अक्षरों का आकार','Lesson text size')}<select id="reading-size">${options([[1,t('सामान्य','Normal')],[1.25,'125%'],[1.5,'150%'],[2,'200%']],prefs.readingScale)}</select></label>${curriculum.sourceLanguage?`<p class="small">${t('पाठ की भाषा','Lesson text language')}: ${e(curriculum.sourceLanguage[prefs.lang])} · ${t('भाषा विकल्प बटन और मेनू बदलता है।','The language option changes buttons and menus.')}</p>`:''}<div class="lesson-tools"><button class="tool-button" data-bookmark="${l.id}" aria-pressed="${saved.includes(l.id)}">${saved.includes(l.id)?'★ '+t('मेरी सूची में है','In my list'):'☆ '+t('मेरी सूची में जोड़ें','Add to my list')}</button><div data-offline-controls="${l.id}">${offlineControls(l)}</div></div>`;}
main.addEventListener('load',ev=>{if(ev.target.matches?.('.full-page img')&&ev.target.naturalWidth)ev.target.parentElement.style.aspectRatio=ev.target.naturalWidth/ev.target.naturalHeight;},true);
main.addEventListener('error',ev=>{if(ev.target.matches?.('.source-crop img')){ev.target.hidden=true;ev.target.parentElement.querySelector('.visual-image-error').hidden=false;}},true);
main.addEventListener('change',ev=>{const id=ev.target.id;if(id==='reading-size'){prefs.readingScale=Number(ev.target.value);persist();main.style.setProperty('--reading-scale',prefs.readingScale);main.dataset.largeText=prefs.readingScale>1.25?'true':'false';return;}if(id==='week'){prefs.week=Number(ev.target.value);prefs.locations[prefs.grade]={week:prefs.week};persist();render({restore:id});}});
main.addEventListener('input',ev=>{if(ev.target.id==='query'){if(ev.isComposing)return;const start=ev.target.selectionStart,end=ev.target.selectionEnd;prefs.query=ev.target.value;render({restore:'query'});$('#query')?.setSelectionRange(start,end);}if(ev.target.matches('[data-note]')){notes[ev.target.dataset.note]=ev.target.value;dirty.add(ev.target.dataset.note);$('#note-status').textContent=t('सहेज रहे हैं…','Saving…');clearTimeout(noteTimer);noteTimer=setTimeout(saveNote,500);}});
main.addEventListener('toggle',ev=>{if(ev.target.matches?.('.search'))prefs.searchOpen=ev.target.open;if(ev.target.matches?.('[data-topic]')){if(ev.target.open){prefs.openTopic=ev.target.dataset.topic;for(const el of main.querySelectorAll('[data-topic]'))if(el!==ev.target)el.open=false;}else if(prefs.openTopic===ev.target.dataset.topic)prefs.openTopic='';persist();updateCurrentContext();}},true);
main.addEventListener('click',async ev=>{const b=ev.target.closest('button,a');if(!b)return;if(b.matches('a[href="#/help"]')&&route.screen!=='help'){helpReturn=location.hash||'#/today';helpScroll=window.scrollY;}if(b.dataset.promptTaught||b.dataset.promptLater){const id=b.dataset.promptTaught||b.dataset.promptLater,record=store.get(KEY+'-taught-prompt',{})||{};if(b.dataset.promptTaught){completed=readObj('-completed');completed[id]=true;const ok=store.set(KEY+'-completed',completed);store.set(KEY+'-taught-prompt',confirmTaught());const l=getLesson(LESSONS,id);render();notify(ok?t('पाठ पढ़ाया गया चिह्नित है।','Lesson marked taught.')+(l?goalProgressText(l):''):t('चिह्न केवल इस सत्र तक रहेगा।','Taught mark kept for this session only.'));}else{store.set(KEY+'-taught-prompt',dismissTaught(record,id,todayKey()));render();}main.querySelector('.today-next a, h1')?.focus?.({preventScroll:true});return;}if(b.hasAttribute('data-open-curriculum')){openCurriculumControls();return;}if(b.hasAttribute('data-export-notes')){flushNotes();downloadText('teacher-notes.txt',notesExportText(curriculum,readObj('-notes'),prefs.lang),'text/plain;charset=utf-8');return;}if(b.hasAttribute('data-content-report')){const l=getLesson(LESSONS,b.dataset.contentReport);downloadText('lesson-content-report.txt',JSON.stringify({curriculum:curriculum.id,lesson:l.id,title:lessonTitle(l),grade:l.grade,week:l.week,day:l.day,source:l.source,page:location.href,appVersion:VERSION,issue:t('समस्या का वर्णन यहाँ लिखें।','Describe the problem here.')},null,2));notify(t('विवरण फ़ाइल डाउनलोड के लिए भेजी गई। इसे जाँचकर साझा करें।','Report file sent to downloads. Review it before sharing.'));return;}if(b.hasAttribute('data-clear-search')){prefs.query='';render();return;}if(b.hasAttribute('data-visual')){openVisual(Number(b.dataset.visual));return;}if(b.dataset.section){ev.preventDefault();jumpToSection(b.dataset.section);return;}if(b.dataset.mode){prefs.mode=b.dataset.mode;prefs.query='';persist();render();return;}if(b.dataset.open){if(route.screen==='find'||route.screen==='saved')listScroll[route.screen]=window.scrollY;prefs.returnTo=route.screen==='saved'?'saved':route.screen==='today'?'today':route.screen==='lesson'?prefs.returnTo:'find';persist();return;}if(b.dataset.bookmark){const id=b.dataset.bookmark;const latest=store.get(KEY+'-saved',[]);saved=Array.isArray(latest)?latest.filter(x=>getLesson(LESSONS,x)):[];const removing=saved.includes(id);saved=removing?saved.filter(x=>x!==id):[...saved,id];const ok=store.set(KEY+'-saved',saved);const y=window.scrollY;render();window.scrollTo(0,y);notify(ok?t(removing?'मेरी सूची से हटाया गया।':'पाठ मेरी सूची में जोड़ा गया।',removing?'Removed from my list.':'Added to my list in this browser.'):t('बुकमार्क केवल इस सत्र तक रखा गया।','Bookmark kept for this session only.'));return;}if(b.dataset.complete){completed=readObj('-completed');const id=b.dataset.complete;if(b.hasAttribute('data-undo'))delete completed[id];else completed[id]=true;const ok=store.set(KEY+'-completed',completed);const y=window.scrollY;render();window.scrollTo(0,y);main.querySelector('[data-complete]')?.focus({preventScroll:true});notify(ok?t(b.hasAttribute('data-undo')?'चिह्न हटा दिया गया।':'पाठ पढ़ाया गया चिह्नित है।',b.hasAttribute('data-undo')?'Taught mark removed.':'Lesson marked taught.')+(b.hasAttribute('data-undo')?'':goalProgressText(getLesson(LESSONS,id))):t('चिह्न केवल इस सत्र तक रहेगा।','Taught mark kept for this session only.'));return;}if(b.hasAttribute('data-save-note')){clearTimeout(noteTimer);const ok=saveNote();notify(ok?t('नोट सहेजा गया।','Note saved.'):t('नोट केवल इस सत्र तक रखा है।','Note kept for this session only.'));return;}if(b.dataset.resource){openReader(b.dataset.resource,Number(b.dataset.grade),Number(b.dataset.page)||0);return;}if(b.dataset.sheet){const l=getLesson(LESSONS,route.id);openReader('workbook',l.grade,0,[b.dataset.sheet]);return;}if(b.hasAttribute('data-review-workbook')){try{const worksheetData=await resourceRepository.worksheets();const ws=worksheetData.filter(w=>w.grade===prefs.grade&&w.week===prefs.week);if(ws.length)openReader('workbook',prefs.grade,0,ws.map(w=>w.image));else notify(t('इस सप्ताह के कार्यपत्रक नहीं मिले।','No worksheets found for this week.'));}catch{notify(t('कार्यपत्रक नहीं खुल पाए। फिर प्रयास करें।','Could not open worksheets. Please retry.'));}return;}if(b.dataset.removeOffline){await removeOffline(b.dataset.removeOffline);return;}if(b.dataset.offline){keepOffline(b.dataset.offline);return;}if(b.hasAttribute('data-print')){const l=getLesson(LESSONS,route.id);openReader('guide',l.grade,l.source.pdfPage-1).then(()=>previewPrint());return;}});
function setSwitcher(open){switcherOpen=open;$('#curriculum-navigation').hidden=!open;$('#current-identity').setAttribute('aria-expanded',String(open));}
function openCurriculumControls(){if(switcherOpen){setSwitcher(false);return;}setSwitcher(true);$('#curriculum-navigation').scrollIntoView({block:'start'});$('#grade').focus({preventScroll:true});}
function updateCurrentContext(){
 const lesson=route.screen==='lesson'?getLesson(LESSONS,route.id):null;
 const section=lesson&&lessonSections(lesson).find(item=>item.id===activeSection);
 const context=describeCurrentContext({pack:curriculum,grade:prefs.grade,lang:prefs.lang,prefs,screen:route.screen,lesson,section:section?sectionLabel(section):null});
 $('#context-title').textContent=context.identity;$('#context-location').textContent=context.location;
 $('#current-context').setAttribute('aria-label',t('वर्तमान कक्षा, विषय और स्थान','Current grade, subject and location'));
 $('#current-identity').setAttribute('aria-label',context.identity+' · '+t('कक्षा या विषय बदलें','Change grade or subject'));
 const back=$('#context-return');back.hidden=route.screen==='find'||route.screen==='today';back.href=route.screen==='lesson'?'#/'+prefs.returnTo:route.screen==='saved'?'#/find':'#/today';back.textContent='← '+(route.screen==='lesson'?returnLabel(prefs.returnTo):route.screen==='saved'?returnLabel('find'):returnLabel('today'));
 document.documentElement.style.setProperty('--context-height',$('#current-context').offsetHeight+'px');
}
$('#current-identity').addEventListener('click',openCurriculumControls);
if('ResizeObserver'in window)new ResizeObserver(()=>{document.documentElement.style.setProperty('--context-height',$('#current-context').offsetHeight+'px');const nav=main.querySelector('.lesson-section-nav');if(nav)main.style.setProperty('--section-nav-height',`${nav.offsetHeight+$('#current-context').offsetHeight+16}px`);}).observe($('#current-context'));
function applyCurriculumSelection(target){if(!target?.pack){notify(t('इस कक्षा और विषय के पाठ अभी उपलब्ध नहीं हैं।','No lessons available for this grade and subject.'));return;}clearTimeout(noteTimer);flushNotes();if(target.pack.id!==curriculum.id){{const u=new URL(selectionURL(location.href,target.pack,target.grade,prefs.lang));if(route.screen==='today'||route.screen==='guide')u.hash=location.hash||'#/today';location.assign(u.href);}return;}prefs.locations={...readObj('').locations,...prefs.locations,[prefs.grade]:{week:prefs.week}};prefs.grade=target.grade;prefs.week=Number(prefs.locations[prefs.grade]?.week)||findLessons(LESSONS,{grade:prefs.grade})[0].week;prefs.openTopic='';prefs.query='';persist();const currentURL=new URL(location.href);if(currentURL.searchParams.has('grade')){currentURL.searchParams.set('grade',String(prefs.grade));history.replaceState(history.state,'',currentURL);}setSwitcher(false);if(route.screen==='lesson'||route.screen==='saved')location.hash='/today';else render();$('#current-identity').focus({preventScroll:true});}
$('#curriculum-navigation').addEventListener('change',ev=>{if(ev.target.id==='grade')applyCurriculumSelection(selectionForGroup(CURRICULA,groupKey(curriculum),Number(ev.target.value),curriculum.subject));else if(ev.target.id==='subject')applyCurriculumSelection({pack:packForSelection(CURRICULA,{group:groupKey(curriculum),grade:prefs.grade,subject:ev.target.value}),grade:prefs.grade});else if(ev.target.id==='curriculum-group')applyCurriculumSelection(selectionForGroup(CURRICULA,ev.target.value,prefs.grade,curriculum.subject));});

$('#ui-language').addEventListener('change',ev=>{clearTimeout(noteTimer);flushNotes();prefs.lang=ev.target.value;persist();const y=window.scrollY;render();window.scrollTo(0,y);$('#reader-close').textContent=t('पाठ पर लौटें','Back to lesson');});
$('.skip-link').addEventListener('click',ev=>{ev.preventDefault();main.focus();main.scrollIntoView({block:'start'});});
window.addEventListener('hashchange',()=>{const wasHelp=route.screen==='help';if($('#reader').open)$('#reader').close();clearTimeout(noteTimer);flushNotes();render({focus:true});alignLessonRoute();if(wasHelp&&location.hash===helpReturn)requestAnimationFrame(()=>window.scrollTo(0,helpScroll));else if(route.screen==='find'||route.screen==='saved')requestAnimationFrame(()=>window.scrollTo(0,listScroll[route.screen]||0));});window.addEventListener('pagehide',flushNotes);
if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js').catch(()=>{});navigator.serviceWorker.addEventListener('controllerchange',()=>offlineController.reset());}
$('#reader-close').textContent=t('पाठ पर लौटें','Back to lesson');render();alignLessonRoute();resourceRepository.load().then(()=>{const l=getLesson(LESSONS,route.id),target=$('#lesson-book-buttons');if(l&&target)target.innerHTML=bookButtons(l);}).catch(()=>{});
